(()=>{"use strict";(()=>{const e=document.querySelector("#timer-hours"),t=document.querySelector("#timer-minutes"),n=document.querySelector("#timer-seconds"),o=()=>{let r=(()=>{let e=(new Date("27 febrary 2025").getTime()-(new Date).getTime())/1e3;return{timeRemaning:e,hours:Math.floor(e/60/60),minutes:Math.floor(e/60%60),seconds:Math.floor(e%60)}})();e.textContent=r.hours,t.textContent=r.minutes,n.textContent=r.seconds,r.timeRemaning>0&&setTimeout(o,1e3)};o()})()})();